const data = $json;

const workflowName = data.workflow?.name || '금융 뉴스 브리핑';
const errorMessage = data.execution?.error?.message || data.error?.message || '알 수 없는 오류';
const failedNode = data.execution?.lastNodeExecuted || data.execution?.error?.node?.name || '알 수 없음';
const executionId = data.execution?.id || '';
const executionUrl = data.execution?.url || (executionId ? `https://app.n8n.cloud/workflow/executions/${executionId}` : '');

function todayKstTime() {
  const now = new Date();
  const kst = new Date(now.getTime() + 9 * 60 * 60 * 1000);
  return kst.toISOString().replace('T', ' ').slice(0, 19);
}

const lines = [
  `⚠️ 브리핑 생성 실패 (${todayKstTime()})`,
  '',
  `워크플로우: ${workflowName}`,
  `실패 지점: ${failedNode}`,
  `오류 내용: ${errorMessage}`,
  '',
  '오늘은 수동으로 뉴스를 확인해 주세요.',
];

if (executionUrl) {
  lines.push('');
  lines.push(`실행 기록: ${executionUrl}`);
}

return [{ json: { message_text: lines.join('\n') } }];
